    pub open spec fn resource(self) -> Sum<A, B> {
        match self {
            SumSP::Left(Some(a), n, true) => Sum::Left(a),
            SumSP::Right(Some(b), n, true) => Sum::Right(b),
            _ => arbitrary(),
